// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherCartel c;

    function setUp() public {
        c = new EtherCartel();
    }

    function _runTest(address caller) internal {
        address oldCeo;
        try c.ceoAddress() returns (address __r) { oldCeo = __r; } catch { return; }
        vm.assume(caller != oldCeo);
        try c.DrugDealer() {} catch { return; }
        assertTrue(c.ceoAddress() == oldCeo);
    }

    function testFuzz_runTest(address caller) public {
        _runTest(caller);
    }

    receive() external payable {}
}
